await (async(page)=>{const ctx=await page.context().browser().newContext({viewport:{width:1600,height:1100}});const p=await ctx.newPage();let progress='startup';const checks=[];const errors=[];p.on('pageerror',e=>errors.push(e.message));try{await p.goto('http://127.0.0.1:5187/?stress=0&audio=0&run=architecture-release-ui-debug');await p.waitForFunction(()=>!!window.__terriStress);if(await p.locator('#close-help').isVisible())await p.locator('#close-help').click();progress='enter Build';await p.locator('#build-toggle').click();await p.waitForFunction(()=>document.body.dataset.building==='true',null,{timeout:5000});await p.locator('#build-tool-walls').click();const setup=await p.evaluate(()=>{const s=window.__terriStress.sim;for(let y=4;y<7;y++)s.setWallEdge(0,18,y,1);s.flushCommands();s.fitWindow(0,18,4,7);s.flushCommands();return Array.from(s.windowPlacements());});progress='pick middle';const c=await p.evaluate(()=>{const c=document.querySelector('#stage'),r=c.getBoundingClientRect(),o=window.__terriStress.origin;return{x:r.left+(o.x+(17.6-5)*32)*r.width/c.width,y:r.top+(o.y+(17.6+5)*21)*r.height/c.height};});await p.mouse.click(c.x,c.y);await p.waitForFunction(()=>!document.querySelector('#window-choices').hidden,null,{timeout:5000});for(let id=1;id<=9;id++)await p.locator('[data-window-model="'+id+'"]').click();checks.push('all9model choices clicked');progress='same model disabled';await p.locator('[data-window-model="7"]').click();await p.waitForFunction(()=>document.querySelector('[data-context-action="fit-window"]')?.disabled===true,null,{timeout:5000});progress='narrower model enabled';await p.locator('[data-window-model="4"]').click();await p.waitForFunction(()=>document.querySelector('[data-context-action="fit-window"]')?.disabled===false,null,{timeout:5000});await p.locator('[data-context-action="fit-window"]').click();progress='replace applied';await p.waitForFunction(()=>Array.from(window.__terriStress.sim.windowPlacements()).join(',')==='0,18,4,4',null,{timeout:5000});checks.push('same-model disabled; narrower enables and applies');await p.locator('#window-back').click();progress='doorway available';await p.locator('[data-context-action="doorway"]').click();await p.waitForFunction(()=>window.__terriStress.sim.lastWallEditResult()?.state===2,null,{timeout:5000});checks.push('Back then Doorway applied');await p.evaluate(()=>{const s=window.__terriStress.sim;s.setWallEdge(0,18,5,1);s.flushCommands();s.fitWindow(0,18,4,7);s.setFloor(4,4,1);s.setFloor(5,4,2);s.setFloor(6,4,3);s.flushCommands();});progress='save';await p.locator('#options-toggle').click();await p.locator('#save-game').click();await p.waitForFunction(()=>/^Saved/.test(document.querySelector('#save-status').textContent),null,{timeout:5000});return{pass:true,progress,checks,setup,errors};}catch(e){await p.screenshot({path:'D:/VIBES/.worktrees/fe58/terrilives/docs/assets/review-evidence/architecture/final/publication-ui-initial.png'});return{pass:false,progress,checks,error:String(e),errors,diag:await p.evaluate(()=>({body:document.body.dataset,save:document.querySelector('#save-status')?.textContent,window:document.querySelector('#window-status')?.textContent,wall:document.querySelector('#wall-status')?.textContent,windows:Array.from(window.__terriStress?.sim.windowPlacements()??[]),actions:Array.from(document.querySelectorAll('[data-context-action]')).map(b=>({id:b.dataset.contextAction,disabled:b.disabled})),origin:window.__terriStress?.origin}))};}finally{await ctx.close();}})(page);
